-- Migration 0009 — Phase 7 invoice + outbox tables: invoices,
-- invoice_templates, invoice_template_versions (DATABASE_DESIGN.md
-- §10.1/§10.3) and email_outbox (§11.1).
-- Generated by drizzle-kit from src/database/schema/invoices.ts and
-- src/database/schema/system.ts, then hand-adjusted per
-- DATABASE_DESIGN.md §13.1:
--   1. Every CREATE TABLE carries the design §2.1 table options
--      ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci.
--   2. The boolean column is written in the design's literal form
--      tinyint(1) NOT NULL DEFAULT 0 (drizzle emitted
--      `boolean ... DEFAULT false`); same adjustment as 0000/0003/0005.
--   3. drizzle-kit also emitted DROP/re-ADD statements for the three
--      circular pages ↔ page_revisions FKs under auto-generated names,
--      plus a DROP of the hand-written FULLTEXT index ft_news_search:
--      the known phantom diffs (see 0005's header). All of them were
--      removed here, and the design FK names / ft_news_search were
--      restored in meta/0009_snapshot.json. A future `db:generate` may
--      re-emit those phantom diffs — remove them the same way.
--   4. The invoice_templates.current_version_id FK is applied under
--      the design name fk_templates_current_version (drizzle-kit
--      generated an auto name); renamed in the snapshot too.
--   5. Tables are created in dependency order (templates → versions →
--      invoices → outbox); all FKs are added by ALTER TABLE once every
--      table exists, because templates ↔ versions reference each other
--      (§10.3's "FK added after versions table" pattern).
--   6. email_outbox.claimed_at is the one column beyond the §11.1
--      listing: Phase 0 amendment A8 requires stale-lease recovery for
--      the drain worker, which is impossible without a claim timestamp.
CREATE TABLE `invoice_templates` (
	`id` bigint unsigned AUTO_INCREMENT NOT NULL,
	`name` varchar(120) NOT NULL,
	`is_active` tinyint(1) NOT NULL DEFAULT 0,
	`current_version_id` bigint unsigned,
	`created_by` bigint unsigned,
	`updated_by` bigint unsigned,
	`created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
	`updated_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
	CONSTRAINT `invoice_templates_id` PRIMARY KEY(`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--> statement-breakpoint
CREATE TABLE `invoice_template_versions` (
	`id` bigint unsigned AUTO_INCREMENT NOT NULL,
	`template_id` bigint unsigned NOT NULL,
	`version_no` int unsigned NOT NULL,
	`config` json NOT NULL,
	`created_by` bigint unsigned,
	`created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
	CONSTRAINT `invoice_template_versions_id` PRIMARY KEY(`id`),
	CONSTRAINT `uq_itv_template_version` UNIQUE(`template_id`,`version_no`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
--> statement-breakpoint
